14	  builders = {
15	    default = version: versionData:
16	      let
17	        system = pkgs.stdenv.hostPlatform.system;
18	        platformData = versionData.${system}
19	          or (throw "gh ${version} has no binary for ${system}");
20	      in
21	      pkgs.stdenv.mkDerivation {
22	        pname = "gh";
23	        inherit version;
24	
25	        src = pkgs.fetchurl {
26	          url = "https://github.com/cli/cli/releases/download/v${version}/gh_${version}_${assetSuffix}";
27	          hash = platformData.sha256;
28	        };
29	
30	        sourceRoot = "gh_${version}_${builtins.replaceStrings [".tar.gz" ".zip"] ["" ""] assetSuffix}";
31	
32	        dontConfigure = true;
33	        dontBuild = true;
34	        dontStrip = true;
35	
36	        nativeBuildInputs = [ pkgs.unzip ] ++ lib.optionals pkgs.stdenv.hostPlatform.isLinux [
37	          pkgs.autoPatchelfHook
38	        ];
39	
40	        buildInputs = lib.optionals pkgs.stdenv.hostPlatform.isLinux [
41	          pkgs.stdenv.cc.cc.lib
42	        ];
43	
44	        installPhase = ''
45	          runHook preInstall
46	          mkdir -p $out/bin
47	          install -m755 bin/gh $out/bin/gh
