49	        '';
50	
51	        meta = with lib; {
52	          description = "GitHub's official command line tool";
53	          homepage = "https://cli.github.com";
54	          license = licenses.mit;
55	          mainProgram = "gh";
56	        };
57	      };
58	  };
59	in
60	{
