1	{ pkgs, lib, toolbox, toolboxLib }:
2	
3	let
4	  inherit (toolboxLib.readData ./data.json) meta versions;
5	
6	  # Map Nix system names to Rust target triples
7	  targetTriple = {
8	    "x86_64-linux"  = "x86_64-unknown-linux-gnu";
9	    "aarch64-linux"  = "aarch64-unknown-linux-gnu";
10	    "x86_64-darwin"  = "x86_64-apple-darwin";
11	    "aarch64-darwin" = "aarch64-apple-darwin";
12	  }.${pkgs.stdenv.hostPlatform.system}
13	    or (throw "Unsupported system: ${pkgs.stdenv.hostPlatform.system}");
14	
15	  builders = {
16	    default = version: versionData:
17	      let
18	        system = pkgs.stdenv.hostPlatform.system;
19	        platformData = versionData.${system}
20	          or (throw "Rust ${version} has no binary for ${system}");
21	      in
22	      pkgs.stdenv.mkDerivation {
23	        pname = "rust";
24	        inherit version;
25	
26	        src = pkgs.fetchurl {
27	          url = "https://static.rust-lang.org/dist/rust-${version}-${targetTriple}.tar.xz";
28	          hash = platformData.sha256;
29	        };
30	
31	        nativeBuildInputs = lib.optionals pkgs.stdenv.hostPlatform.isLinux [
32	          pkgs.autoPatchelfHook
33	        ];
34	
35	        buildInputs = lib.optionals pkgs.stdenv.hostPlatform.isLinux [
36	          pkgs.stdenv.cc.cc.lib  # libgcc_s.so.1
37	          pkgs.zlib              # libz.so.1
38	        ];
39	
40	        dontConfigure = true;
41	        dontBuild = true;
42	        dontStrip = true;
43	
44	        installPhase = ''
45	          runHook preInstall
46	
47	          bash install.sh \
48	            --prefix=$out \
49	            --components=rustc,cargo,rust-std-${targetTriple},clippy-preview,rustfmt-preview \
50	            --disable-ldconfig
51	
52	          # Remove installation manifest (not needed in Nix store)
53	          rm -rf $out/lib/rustlib/{manifest-*,install.log,rust-installer-version,components,uninstall.sh}
54	
55	          runHook postInstall
56	        '';
57	
58	        passthru = {
59	          targetPlatforms = lib.platforms.all;
60	          badTargetPlatforms = [ ];
61	        };
62	
63	        meta = {
64	          description = "Rust toolchain (pre-built binary from static.rust-lang.org)";
65	          homepage = "https://www.rust-lang.org/";
66	          license = with lib.licenses; [ asl20 mit ];
67	          platforms = [
68	            "x86_64-linux"
69	            "aarch64-linux"
70	            "x86_64-darwin"
71	            "aarch64-darwin"
72	          ];
73	        };
74	      };
75	  };
76	in
77	{
78	  versions = toolboxLib.buildVersions "rust" builders versions;
79	  default = meta.default;
80	}
